effect.shader:
float hash(vec2 p) { return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453); }

void main() {
    vec2 uv = acScreenNorm;
    vec4 c = texture(inputImg, uv);
    float L = dot(c.rgb, vec3(0.2126, 0.7152, 0.0722));
    float boosted = clamp(L * gain, 0.0, 1.0);

    // tint em verde
    vec3 col = mix(vec3(boosted), tint.rgb * boosted * 1.4, 0.85);

    // scanlines horizontais
    float sl = 1.0 - scanlines * 0.5 * (0.5 + 0.5 * sin(uv.y * acResolution.y * 3.14159));
    col *= sl;

    // grão
    float n = hash(uv * acResolution + fract(acTime));
    col += (n - 0.5) * grain;

    // vinheta radial
    vec2 d = uv - 0.5;
    float v = 1.0 - smoothstep(0.3, 0.9, length(d) * 1.4) * vignette;
    col *= v;

    fragColor = vec4(clamp(col, 0.0, 1.0), c.a);
}
